// Voice/AiVoice/AiVoiceController.cs
using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using FindAncestor.AiVoice;
using FindAncestor.ErrorDialog;
namespace FindAncestor.AiVoice { public class AiVoiceController { private readonly Mp4ToWavService _mp4 = new(); private readonly DemucsService _demucs = new(); private readonly NoiseReductionService _noise = new(); private readonly AudioSplitService _split = new(); private readonly DatasetValidationService _ds = new(); private readonly RvcTrainingService _rvc = new(); private readonly ModelValidationService _mv = new(); private CancellationTokenSource? _cts; public event Action<AiVoiceProgress>? OnProgress; private void Report(string p, double per) { OnProgress?.Invoke(new AiVoiceProgress { Phase = p, Percentage = per }); } public async Task RunAsync(string mp4) { try { _cts = new CancellationTokenSource(); var work = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "AiVoiceWork", DateTime.Now.ToString("yyyyMMdd_HHmmss")); Directory.CreateDirectory(work); var model = new AiVoiceModel { InputMp4Path = mp4, WorkingDirectory = work }; Report("mp4→wav", 10); await _mp4.ConvertAsync(model.InputMp4Path, model.WavPath); Report("demucs", 30); var demucsOut = Path.Combine(work, "demucs"); await _demucs.ExtractVocalsAsync(model.WavPath, demucsOut); var vocal = _demucs.ResolveVocalPath(demucsOut, model.WavPath); if (string.IsNullOrEmpty(vocal)) return; Report("clean", 50); await _noise.CleanAsync(vocal, model.CleanPath); Report("split", 70); await _split.SplitAsync(model.CleanPath, model.DatasetPath); if (!_ds.Validate(model.DatasetPath)) return; Report("train", 90); await _rvc.TrainAsync(model.DatasetPath, model.ModelOutputPath); if (!_mv.Validate(model.ModelOutputPath)) return; Report("完了", 100); } catch (Exception ex) { ErrorDialogService.Show(ex); } } public void Cancel() { try { _cts?.Cancel(); } catch (Exception ex) { ErrorDialogService.Show(ex); } } } }